INSERT INTO "cms_sections" ("id", "section_key", "title", "subtitle", "content", "cta_text", "cta_link", "image_url", "extra_data", "sort_order", "is_enabled", "updated_at") VALUES ('cmvxn9ix70041ju794rsvj4t5', 'hero', 'Made for Little Wonders', 'Delicately soft, 100% combed organic cotton baby apparel. Hypoallergenic, kind to sensitive skin, and crafted with conscious love.', NULL, 'Explore Collection', '/shop', '/images/hero/hero_baby_lifestyle.jpg', NULL, 0, TRUE, '2026-11-01T12:08:22.459Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "cms_sections" ("id", "section_key", "title", "subtitle", "content", "cta_text", "cta_link", "image_url", "extra_data", "sort_order", "is_enabled", "updated_at") VALUES ('cmvxn9j270042ju79q42jd3uh', 'brandStory', 'Born from Pure Love in Rajkot', 'Our In-House Craftsmanship & Promise', 'At Little Cuckoo, we believe baby clothes should feel like a tender embrace. Manufactured in our own clean textile unit in Rajkot, Gujarat (Anant Garments), every single stitch, nickel-free snap, and organic fiber is inspected by experienced hands. No harmful azo dyes, no scratchy tags, only cloud-like softness for your precious newborn.', 'Read Our Story', '/about', '/images/products/newborn_welcome_gift_set.jpg', NULL, 0, TRUE, '2026-11-01T12:08:22.615Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "cms_sections" ("id", "section_key", "title", "subtitle", "content", "cta_text", "cta_link", "image_url", "extra_data", "sort_order", "is_enabled", "updated_at") VALUES ('cmvxtdjlb0000o9b1cmtlbzlt', 'lifestyle', 'Little Looks, Big Smiles', 'LITTLE LOOKS, BIG SMILES', 'Real little wonders enjoying everyday snuggles in our gentle organic cotton fabrics.', 'Shop The Looks', '/shop', NULL, '[{"id":"look-1","title":"Morning Snuggles in Ribbed Knit","badge":"EVERYDAY LITTLE JOYS","productSlug":"cloudsoft-organic-cotton-ribbed-romper","productTitle":"CloudSoft Ribbed Romper","price":699,"image":"/images/hero/hero_baby_lifestyle.jpg","featured":true},{"id":"look-2","title":"Newborn Welcome Starter Set","badge":"SOFTNESS IN EVERY MOMENT","productSlug":"newborn-welcome-5-piece-organic-set","productTitle":"5-Piece Newborn Gift Box","price":1499,"image":"/images/products/newborn_welcome_gift_set.jpg","featured":false},{"id":"look-3","title":"Buttercup Yellow Zip Sleepsuit","badge":"DREAMY NAPTIMES","productSlug":"sweet-dreams-bamboo-organic-cotton-sleepsuit","productTitle":"Two-Way Zip Sleepsuit","price":799,"image":"/images/products/buttercup_zip_sleepsuit.jpg","featured":false},{"id":"look-4","title":"Heirloom Hand-Smocked Frock","badge":"MADE WITH LOVE","productSlug":"little-flora-heirloom-embroidered-dress-set","productTitle":"Heirloom Dress & Bloomer","price":1199,"image":"/images/products/heirloom_baby_dress.jpg","featured":false},{"id":"look-5","title":"Sweet Pea Muslin Swaddles","badge":"PURE ORGANIC GOTS","productSlug":"little-wonders-luxury-baby-shower-keepsake-hamper","productTitle":"Muslin Swaddle Duo","price":599,"image":"/images/products/muslin_swaddle_duo.jpg","featured":false}]', 0, TRUE, '2026-11-01T12:36:27.119Z') ON CONFLICT ("id") DO NOTHING;
